m.AUTHORED.update({
23:dict(title='Paghiwalay sa density at katangian ng materyal laban sa puwersa',objective='Ihiwalay ang density, elasticity, plasticity, at toughness; huwag pumili ng materyal mula sa iisang katangian lamang.',paragraphs=[
('Prinsipyo at papel ng proseso','Ang density ay masa sa bawat yunit ng volume. Kahit pareho ang volume, magbabago ang masa kung iba ang materyal. Elasticity ang katangiang bumabalik ang deformation matapos alisin ang puwersa; plasticity naman kung nananatili ito. Magkaiba rin ang hardness at toughness, na kakayahang hindi madaling masira sa impact. Hindi sapat ang salitang “magaan” o “matigas” upang pasyahan kung angkop sa gamit.'),
('Tiyak na pagpapasya sa trabaho','Isaalang-alang ang piyesang may volume na 20 cm³. Sa pagkukuwentang ipinagpalagay na 2.70 g/cm³ ang density ng aluminum at 7.87 g/cm³ ang bakal, ang masa ay 54.0 g at 157.4 g. Gayunman, huwag palitan ng aluminum ang itinakdang bakal na piyesa dahil lamang mas magaan. Kailangan ding tiyakin ang lakas, deformation, temperatura, at iba pang kondisyon. Nagkakaiba ang density ayon sa materyal at alloy.'),
('Kondisyon at rekord na dapat tiyakin','Kapag binaluktot ang manipis na sheet at inalis ang puwersa, maaaring bahagyang bumalik ito. Mas madaling maunawaan ang hugis matapos gawin kung ihihiwalay ang pagbalik dahil sa elasticity at plastic deformation na nananatili bilang hugis. Huwag tukuyin ang uri ng materyal mula lamang sa hitsura, kulay, o pakiramdam sa paghawak; tiyakin ang material marking at rekord. Kasama sa pagbabago ng materyal ang pagpapasya sa disenyo at kalidad.')],terms=['Masa sa bawat yunit ng volume.','Katangiang bumabalik ang deformation kapag inalis ang puwersa.','Katangiang nananatili ang deformation kahit inalis ang puwersa.','Katatagang hindi madaling masira sa impact at katulad nito.'],fullActivity=act('Kalkulahin ang masa para sa volume na 10 cm³ gamit ang parehong ipinagpalagay na density. Magsulat ng tatlong kondisyong dapat tiyakin bukod sa density sa pagpili ng materyal. Ihiwalay rin ang halimbawa ng elasticity at plasticity.'),safety=['Huwag gawin o ipadala bilang itinakdang materyal ang hindi kilalang materyal batay lamang sa hitsura.'],summary='Kaugnay ng masa ang density; kaugnay ng pagbalik ng deformation ang elasticity at plasticity. Hiwalay na tiyakin ang hardness, toughness, at kondisyon ng gamit.'),
24:dict(title='Pagkilala sa heat treatment ng bakal ayon sa layunin',objective='Ihiwalay ang layunin ng quenching, tempering, annealing, at surface hardening.',paragraphs=[
('Prinsipyo at papel ng proseso','Binabago ng heat treatment ang istruktura at katangian ng metal sa pamamagitan ng kondisyon ng pag-init at paglamig. Sa karaniwang treatment ng bakal, ginagamit ang quenching upang pataasin ang hardness, at tempering upang iakma ang hardness at toughness matapos quenching. Layunin ng annealing na palambutin upang mas madaling i-machine at katulad nito. Hindi lahat ng metal ay titigas nang magkapareho sa parehong pag-init at paglamig.'),
('Tiyak na pagpapasya sa trabaho','Sa process sheet ng kathang-isip na tool part, nakasulat na “Pagkatapos ng quenching, i-temper sa itinakdang kondisyon.” Huwag ipasyang tapos na dahil tumigas matapos quenching; tiyakin ang pagkumpleto ng buong proseso kasama ang tempering at inspeksiyon. Gayundin, hindi maaaring palitan ng quenching ang tagubiling palambutin para sa susunod na machining dahil lamang magkahawig ang pangalan.'),
('Kondisyon at rekord na dapat tiyakin','Pinabubuti ng surface hardening ang katangian ng ibabaw, kaya hindi laging pareho ang kondisyon sa loob at ibabaw. Sa welding, may heat-affected zone din sa paligid bukod sa natunaw na bahagi. Itugma ang materyal, layunin ng treatment, temperatura, oras, cooling conditions, at resulta ng inspeksiyon. Ang paliwanag sa materyal na ito ay hindi work instruction para itakda ang heat-treatment conditions.')],terms=['Treatment na nagpapataas ng hardness ng bakal at katulad nito sa mabilis na paglamig matapos ang angkop na pag-init.','Muling pag-init matapos quenching upang iakma ang hardness at toughness.','Treatment ng pag-init at paglamig para sa pagpapalambot o pag-aayos ng istruktura.','Bahagi sa paligid na nagbago ang istruktura o katangian dahil sa init ng welding at katulad nito.'],fullActivity=act('Para sa pagpapataas ng hardness, pag-aakma ng katangian matapos quenching, pagpapadali ng machining, at pagpapatigas ng ibabaw lamang, isulat ang kaukulang treatment at process record na dapat tiyakin.'),safety=['May panganib ang furnace, mainit na materyal, at cooling medium. Huwag baguhin ang temperatura o paraan ng paglamig sa sariling pagpapasya.'],summary='Iugnay ang pangalan ng treatment sa layunin. Huwag ipaghalo ang quenching at annealing; tiyakin ang buong itinakdang proseso.'),
25:dict(title='Paghiwalay sa galaw ng lathe, milling machine, at drilling machine',objective='Ipaliwanag ang gamit ng cutting machine mula sa galaw ng workpiece at tool.',paragraphs=[
('Prinsipyo at papel ng proseso','Sa cutting, inaalis ng tool ang materyal upang makuha ang nais na hugis. Sa lathe, karaniwang pinaikot ang workpiece at inilalapat ang tool upang gawin ang panlabas na diyametro at katulad nito. Sa milling machine, umiikot ang tool at ginagawa ang patag o uka sa relatibong galaw ng tool at workpiece. Sa drilling machine, umiikot ang drill upang gumawa ng butas. Mas madaling maunawaan ang papel ng makina at mapanganib na bahagi kung malinaw kung alin ang umiikot.'),
('Tiyak na pagpapasya sa trabaho','Isaalang-alang ang pag-aayos ng panlabas na diyametro ng bilog na bar at kasunod na paggawa ng patag na mounting face at butas. Maaaring piliin ang lathe para sa diyametro, milling machine para sa patag, at drilling machine para sa butas, ngunit drawing, kakayahan ng kagamitan, at aprubadong process sheet ang batayan ng aktuwal na proseso. Huwag ipasyang lathe lamang hanggang matapos dahil bilog ang materyal. May automatic tool changer ang machining center at maaari itong gumawa ng maraming uri ng machining.'),
('Kondisyon at rekord na dapat tiyakin','Nagkakaroon ng init at chips sa cutting. May papel ang cutting oil at coolant sa pagpapalamig, pagbabawas ng tool wear, at paglabas ng chips, ngunit huwag ipasyang nalutas ang kakaibang tunog o finish sa pagdagdag lamang ng likido. Itugma sa rekord ang pagkakakabit, tool, at machining conditions. May errata sa mga numero ng figure sa pinagmulang materyal, kaya tiyakin ang pahina at pangalan ng makina sa pagsangguni.')],terms=['Materyal o piyesang ginagawan ng machining.','Machine tool na nagpuputol gamit ang tool habang umiikot ang workpiece.','Machine tool na gumagawa ng patag o uka gamit ang umiikot na tool.','Machine tool na may kakayahang awtomatikong magpalit ng tool.'],fullActivity=act('Para sa paggawa ng panlabas na diyametro, patag, at butas, gumawa ng talaan ng umiikot na bagay, layunin ng hugis, at kinakailangang pagtiyak sa pagkakakabit.'),safety=['Huwag hawakan ang umiikot na bahagi. Sa pag-alis ng chips at pagsukat, sundin ang pamamaraan ng paghinto at pagtiyak ng kaligtasan.'],summary='Ihiwalay ang cutting machines ayon sa galaw ng tool at workpiece. Ihiwalay ang posibleng kagamitan sa aktuwal na aprubadong proseso.'),
26:dict(title='Paghiwalay sa layunin ng grinding at polishing',objective='Ihiwalay ang dimensional accuracy sa surface finish; huwag ipasyang tapos ang machining mula sa hitsura lamang.',paragraphs=[
('Prinsipyo at papel ng proseso','Unti-unting nag-aalis ng materyal ang grinding gamit ang abrasive grains ng grinding wheel. Ginagamit ito sa pagtatapos ng matigas na materyal o surface na nangangailangan ng mataas na dimensional accuracy. Inaayos naman ng polishing ang surface gamit ang polishing compound at katulad nito. Maaaring layunin ang hitsura, roughness, o friction, ngunit hindi ibig sabihing mas makintab ay mas mahusay sa lahat ng gamit. Hiwalay na tiyakin ang dimensiyon at kondisyon ng surface na hinihingi ng drawing.'),
('Tiyak na pagpapasya sa trabaho','Kahit makintab ang surface ng shaft, hindi ito papasa sa dimensiyon kung lampas sa upper limit ang panlabas na diyametro. Kahit tugma naman ang dimensiyon, kailangang hiwalay na tiyakin ang kinakailangang surface roughness. Sa muling finishing, magbabago ang dimensiyon kapag kinayod, kaya tiyakin muna ang natitirang machining allowance at aprubadong hakbang bago gawin.'),
('Kondisyon at rekord na dapat tiyakin','Dapat angkop ang grinding wheel at polishing compound sa materyal, layunin ng machining, at kondisyon ng kagamitan. Hindi maaaring palitan nang walang pahintulot ng bagay na magkahawig lamang. Itugma pagkatapos ng trabaho ang ginawang bahagi at resulta ng inspeksiyon; huwag gawing kapalit ng sukat ang kintab ng surface. Hindi kapalit ang araling ito ng kinakailangang kwalipikasyon at edukasyon para sa pagpapalit ng grinding wheel at trial run.')],terms=['Machining na unti-unting nag-aalis ng materyal gamit ang abrasive grains ng grinding wheel at katulad nito.','Pag-aayos ng surface gamit ang polishing compound at katulad nito.','Tool para sa machining na may hawak na abrasive grains.','Dami ng materyal na sadyang iniwan upang alisin sa finishing at katulad na proseso.'],fullActivity=act('Gumawa ng inspection note na naghihiwalay sa requirement at paraan ng pagtiyak para sa panlabas na diyametro, surface roughness, at kintab. Isulat ang dalawang bagay na dapat tiyakin bago rework.'),safety=['Sundin ang kinakailangang edukasyon at pamamaraan sa pagpapalit ng grinding wheel at trial run. Huwag ilapit ang kamay sa umiikot na grinding wheel o polishing area.'],summary='Ihiwalay ang layunin ng grinding at polishing. Huwag ituring na iisang item ng paghatol ang dimensiyon, roughness, at kintab.')
})
